"""Latest verified measurements, separate from frozen campaign comparisons."""
from pathlib import Path
from flask import abort,jsonify,render_template_string,request,send_file
from latest_results import load_latest,result_path


def number(value,digits=2,scale=1):
    return '—' if value is None else format(value/scale,f',.{digits}f')


def register_latest(app):
    @app.route('/api/latest')
    def latest_api():
        try:return jsonify(load_latest())
        except (ValueError,OSError,KeyError,TypeError) as exc:return jsonify(error=str(exc),status='evidence_error'),409

    @app.route('/')
    def latest_index():
        try:
            data=load_latest();overview=[]
            for kind in ('functional','finite-budget'):
                candidates=[r for r in data['runs'] if r['mode']=='P1' and r['category']==kind]
                if candidates:overview.append(max(candidates,key=lambda r:r['run_id']))
            finite=next((r for r in overview if r['category']=='finite-budget'),None)
            chart={'curve':finite['energy_curve'],'horizon':finite['horizon_seconds'],'lifetime':finite['summary']['lifetime']} if finite else None
            return render_template_string(PAGE,data=data,overview=overview,chart=chart,fmt=number)
        except (ValueError,OSError,KeyError,TypeError) as exc:
            return render_template_string('<h1>Latest evidence unavailable</h1><p>{{error}}</p><a href="/campaign">Historical campaign</a>',error=str(exc)),503

    @app.route('/api/latest/artifact')
    def latest_artifact():
        try:data=load_latest()
        except (ValueError,OSError,KeyError,TypeError) as exc:return jsonify(error=str(exc)),409
        directory=request.args.get('run','');name=request.args.get('name','')
        row=next((r for r in data['runs'] if r['directory']==directory),None)
        if row is None or name not in row['artifacts']:abort(404)
        run=result_path(directory);path=(run/name).resolve()
        if not path.is_relative_to(run) or not path.is_file():abort(403)
        return send_file(path,as_attachment=True,download_name=row['run_id']+'-'+Path(name).name)

    @app.route('/api/latest/export')
    def latest_export():
        try:data=load_latest()
        except (ValueError,OSError,KeyError,TypeError) as exc:return jsonify(error=str(exc)),409
        response=jsonify(data);response.headers['Content-Disposition']='attachment; filename=latest-verified-results.json';return response


PAGE=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AdaptiveAlpha · Latest verified results</title>
<style>
:root{--ink:#15283f;--muted:#566a80;--line:#dbe5ed;--bg:#f3f6fa;--teal:#087e85;--orange:#ab570b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,-apple-system,sans-serif}header{background:#11263b;color:white;padding:20px max(24px,calc((100vw - 1360px)/2));display:flex;align-items:center;gap:24px;flex-wrap:wrap}header strong{font-size:21px;letter-spacing:-.5px}header small{color:#bcd0e0}nav{margin-left:auto;display:flex;gap:20px}nav a{color:#d6e8f3;text-decoration:none}main{max-width:1408px;margin:auto;padding:32px 24px 60px}h1{font-size:36px;line-height:1.15;letter-spacing:-1.2px;margin:8px 0 12px}h2{font-size:21px;letter-spacing:-.4px;margin:0 0 6px}h3{font-size:19px;margin:8px 0 4px}p{margin:8px 0}.muted{color:var(--muted)}.kicker{font-size:12px;font-weight:800;letter-spacing:1.7px;color:var(--teal);text-transform:uppercase}.hero{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:26px}.actions{display:flex;gap:10px;white-space:nowrap}a{color:#096e9d}button,.button{font:inherit;border:1px solid var(--line);border-radius:8px;background:white;padding:9px 14px;color:var(--ink);cursor:pointer;text-decoration:none}a:focus-visible,button:focus-visible,select:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #258bcb;outline-offset:3px}.button.primary{background:var(--teal);border-color:var(--teal);color:white}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:22px 0}.stat{border:1px solid var(--line);background:white;border-radius:10px;padding:15px 20px}.stat b{display:block;font-size:27px;letter-spacing:-.7px}.stat small{color:var(--muted)}.two{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panel{background:white;border:1px solid var(--line);border-radius:12px;padding:24px;margin-bottom:22px;box-shadow:0 3px 10px #15283f04}.p1{border-top:4px solid var(--teal)}.p1.finite-budget{border-top-color:#cf7a27}.badge{font-size:11px;font-weight:750;padding:4px 8px;border-radius:5px;background:#e0f3ed;color:#146449;display:inline-block}.badge.amber{background:#fff0dc;color:#8d4d09}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:20px 0}.metric span{display:block;color:var(--muted);font-size:12px}.metric b{font-size:26px;letter-spacing:-.6px}.unit{font-size:13px;color:var(--muted)}.small{font-size:12px}.note{border-left:3px solid #a4bdd1;background:#f3f7fb;padding:10px 14px;color:#3f5871;font-size:13px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:8px 0 15px}.overflow{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px}th{text-align:left;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.6px;background:#f5f8fb;position:sticky;top:0}td,th{padding:12px;border-bottom:1px solid var(--line);vertical-align:top;white-space:nowrap}tr:last-child td{border-bottom:0}.mono{font:11px ui-monospace,monospace}.filters{display:flex;gap:10px}input,select{font:inherit;border:1px solid var(--line);border-radius:7px;padding:8px 10px;background:white;color:var(--ink)}summary{cursor:pointer;color:#096e9d}.downloads a{display:block;margin:7px 0}.limits{display:grid;grid-template-columns:1fr 1fr;gap:8px 24px;padding-left:20px;color:var(--muted);font-size:13px}#energy-chart{width:100%;height:300px;display:block}.chart-labels{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;color:var(--muted)}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px}footer{font-size:12px;color:var(--muted);margin-top:20px}@media(max-width:850px){.hero{display:block}h1{font-size:29px}.actions{margin-top:16px}.two{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.section-head{display:block}.filters{margin-top:12px;flex-wrap:wrap}.limits{grid-template-columns:1fr}main{padding:24px 14px}.panel{padding:18px}nav{margin-left:0;gap:14px}.metric b{font-size:23px}}
</style></head><body>
<header><div><strong>AdaptiveAlpha IoT</strong><br><small>Research evidence · latest verified snapshot</small></div><nav><a href="#p1">P1 results</a><a href="#security">Security</a><a href="/campaign">Earlier campaign</a><a href="/historical">Full archive</a></nav></header>
<main><div class="hero"><div><div class="kicker">Z1 emulation · 1 root + 2 sensors</div><h1>Latest P1 measurements</h1><p class="muted">Verified recorded results, with functional delivery and finite-budget mechanisms kept separate.</p></div><div class="actions"><button onclick="location.reload()">Refresh</button><a class="button primary" href="/api/latest/export">Export verified data</a></div></div>
<div class="stats"><div class="stat"><b>{{data.verified_runs}}</b><small>Verified calibration / mechanism runs</small></div><div class="stat"><b>{{data.artifact_binary_checks}}</b><small>Artifact + binary hashes matched</small></div><div class="stat"><b>{{data.evaluation_seeds|length}}</b><small>Evaluation seed · {{data.evaluation_seeds|join(', ')}}</small></div><div class="stat"><b>Modelled energy</b><small>Z1 component model · not physical battery data</small></div></div>
<section id="p1" class="two">
{% for r in overview %}{% set s=r.summary %}{% set wire=s.mechanism_checks.policy_wire %}
<article class="panel p1 {{r.category}}"><span class="badge {% if r.category=='finite-budget' %}amber{% endif %}">{{'FINITE-BUDGET MECHANISM' if r.category=='finite-budget' else 'FUNCTIONAL WORKLOAD'}}</span><h3>P1 · {{'finite sensor budgets' if r.category=='finite-budget' else 'authenticated delivery'}}</h3><p class="muted small">One run · seed {{r.seed}} · qualified for its recorded measurement source</p>
<div class="metrics"><div class="metric"><span>Energy / authenticated delivery</span><b>{{fmt(s.energy_per_delivered_reading_nj,2,1000000)}}</b> <small class="unit">mJ</small></div><div class="metric"><span>Authenticated / generated readings</span><b>{{s.unique_authenticated_delivered}} / {{s.generated}}</b></div><div class="metric"><span>Reading PDR</span><b>{{fmt(s.reading_pdr*100)}}%</b></div><div class="metric"><span>p95 end-to-end delay</span><b>{{fmt(s.p95_delay_ms)}}</b> <small class="unit">ms</small></div></div>
<p class="small">{{s.packets_submitted}} packets · profiles {{wire.tx_profiles|join(' / ')}} · caps {{s.policy.caps_used|join(' / ')}} · {{wire.wire_profile_changes}} actual wire profile changes</p>
{% if s.lifetime %}<p class="note">Demand: {{s.lifetime.scheduled_delivered}} / {{s.lifetime.scheduled_readings}} scheduled readings delivered. {{s.explicit_drops}} explicit drops. Budget {{fmt(r.budget_nj,3,1000000000)}} J per sensor; root unbounded.</p>{% else %}<p class="note">{{s.policy.total_switches}} logged action changes include decisions without subsequent traffic. No fallback actions: {{s.policy.fallback_actions}}.</p>{% endif %}
<details class="small"><summary>Run identity & evidence</summary><p class="mono">{{r.run_id}}</p><a href="{{url_for('api_run',run_id=r.directory.removeprefix('results/'))}}" target="_blank" rel="noopener">Full manifest / summary / events</a> · <a href="{{url_for('latest_artifact',run=r.directory,name='COOJA.testlog')}}">Raw log</a></details></article>
{% endfor %}</section><p class="muted small">Each card is a single run, not a pooled mean. Different budgets / service denominators prevent a direct energy-superiority comparison. No confidence interval is implied.</p>
{% if chart %}<section class="panel"><div class="section-head"><div><h2>Finite-budget P1 · battery and service timeline</h2><p class="muted small">Actual ENERGY_MODEL samples. Lines stop at each node's final sample; no assumed post-death values.</p></div><span class="badge">Terminal accounting verified</span></div><svg id="energy-chart" viewBox="0 0 1120 300" role="img" aria-label="Remaining model energy for sensor nodes 2 and 3 over global simulation time"><title>Measured component-model remaining energy</title></svg><div class="chart-labels"><span><i class="dot" style="background:#07838b"></i>Node 2</span><span><i class="dot" style="background:#725ac1"></i>Node 3</span><span>FND/HND: {{fmt(chart.lifetime.fnd.time_ms,3,1000)}} s</span><span>Service crossing: {{fmt(chart.lifetime.functional.crossing_ms,0,1000)}} s</span><span>Confirmation: {{fmt(chart.lifetime.functional.confirmation_ms,0,1000)}} s</span></div></section>{% endif %}
<section class="panel"><h2>Depletion & scheduled service</h2><p class="muted small">Separate mechanism cells. HND may equal FND for a two-node battery population. Root budget is unbounded.</p><div class="overflow"><table><thead><tr><th>Run</th><th>Bounded sensors</th><th>Generated PDR</th><th>Scheduled delivered</th><th>FND / HND (s)</th><th>Service crossing / confirmed (s)</th><th>Post-death violations</th></tr></thead><tbody>{% for r in data.runs if r.category=='finite-budget' %}{% set s=r.summary %}{% set life=s.lifetime %}<tr><td>{{r.name}}</td><td>{{'all sensors' if not r.bounded_node else 'node '~r.bounded_node}}</td><td>{{fmt(s.reading_pdr*100)}}%</td><td>{{life.scheduled_delivered}} / {{life.scheduled_readings}}</td><td>{{fmt(life.fnd.time_ms,3,1000)}} / {{fmt(life.hnd.time_ms,3,1000)}}</td><td>{{fmt(life.functional.crossing_ms,0,1000)}} / {{fmt(life.functional.confirmation_ms,0,1000)}}</td><td>{{s.mechanism_checks.depletion.post_death_application_or_rf_violations}}</td></tr>{% endfor %}</tbody></table></div><p class="note">Bottleneck control: its service threshold failed before node death. Cutoff/accounting is verified; that first service failure is not attributed to depletion.</p></section>
<section class="panel" id="security"><h2>Security fixtures · positive controls and refusal evidence</h2><p class="muted small">Dedicated tests, excluded from energy comparisons. Reset checks prove fail-closed refusal without a new boot grant.</p><div class="overflow"><table><thead><tr><th>Fixture</th><th>Injections / rejections</th><th>Post-reset probes</th><th>Locked refusals</th><th>Post-reset accepted</th><th>Status</th></tr></thead><tbody>{% for r in data.runs if r.category=='security' %}{% set s=r.summary %}{% set reset=s.mechanism_checks.get('root_reset') %}<tr><td>{{r.name}}</td><td>{% if not reset %}{{s.security_test_injections}} / {{s.security_test_rejections}}{% else %}—{% endif %}</td><td>{{reset.post_reset_probes if reset else '—'}}</td><td>{{reset.locked_context_rejections if reset else '—'}}</td><td>{{reset.post_reset_acceptances if reset else '—'}}</td><td><span class="badge">Verified</span></td></tr>{% endfor %}</tbody></table></div></section>
<section class="panel"><h2>Recorded-source calibration · all six measured cells</h2><p class="muted small">Calibration seed {{data.calibration_seeds|join(', ')}} · n=1 per cell · separate from evaluation. A configured cap is not a guaranteed packet occupancy.</p><div class="overflow"><table><thead><tr><th>Profile</th><th>Configured cap</th><th>Actual batch counts</th><th>PDR</th><th>p95 (ms)</th><th>Energy / auth. reading (mJ)</th></tr></thead><tbody>{% for r in data.runs if r.category=='calibration' %}<tr><td>{{'AES-128-CCM' if r.profile==1 else 'Ascon-AEAD128'}}</td><td>{{r.configured_cap}}</td><td>{{r.summary.batch_counts|join(', ')}}</td><td>{{fmt(r.summary.reading_pdr*100)}}%</td><td>{{fmt(r.summary.p95_delay_ms)}}</td><td>{{fmt(r.summary.energy_per_delivered_reading_nj,4,1000000)}}</td></tr>{% endfor %}</tbody></table></div></section>
<section class="panel"><div class="section-head"><div><h2>Exact run ledger</h2><p class="muted small">Every row is an actual run. Filters do not pool or recalculate metrics.</p></div><div class="filters"><select id="purpose-filter" aria-label="Filter run purpose"><option value="">All purposes</option><option>functional</option><option>finite-budget</option><option>security</option><option>calibration</option></select><input id="run-search" type="search" placeholder="Search run / mode…" aria-label="Search runs"></div></div><div class="overflow"><table id="runs"><thead><tr><th>Purpose / role</th><th>Mode</th><th>Seed</th><th>Run ID</th><th>Checks</th><th>Evidence</th></tr></thead><tbody>{% for r in data.runs %}<tr data-category="{{r.category}}"><td>{{r.category}}<br><span class="small muted">{{r.name}}</span></td><td>{{r.mode}}</td><td>{{r.seed}}</td><td class="mono">{{r.run_id}}</td><td><span class="badge">{{r.artifact_checks}} matched</span></td><td><details class="downloads"><summary>Files & detail</summary><a href="{{url_for('api_run',run_id=r.directory.removeprefix('results/'))}}" target="_blank" rel="noopener">Full run detail (JSON)</a>{% for name in r.artifacts if name in ['manifest.json','summary.json','COOJA.testlog','events.jsonl','generated-conf.h','scenario.csc','mechanism-checks.json'] or name.startswith('binaries/') %}<a href="{{url_for('latest_artifact',run=r.directory,name=name)}}">{{name}}</a>{% endfor %}</details></td></tr>{% endfor %}</tbody></table></div><p id="visible-count" class="small muted">{{data.verified_runs}} runs shown</p></section>
<section class="panel"><h2>How to read these results</h2><ul class="limits">{% for limit in data.limitations %}<li>{{limit}}</li>{% endfor %}</ul><p class="small muted">Artifact verification refers to the recorded measurement source and immutable files. Presentation changes do not requalify tables for a future firmware run.</p></section><footer>Snapshot: {{data.validation_directory}} · <a href="/api/latest">Verified JSON</a> · <a href="/campaign">Earlier frozen campaign</a> · <a href="/historical">All preserved records</a></footer></main>
<script>
const chart={{chart|tojson}};
const purpose=document.getElementById('purpose-filter'),search=document.getElementById('run-search');
function filterRuns(){let n=0;document.querySelectorAll('#runs tbody tr').forEach(row=>{const visible=(!purpose.value||row.dataset.category===purpose.value)&&row.textContent.toLowerCase().includes(search.value.toLowerCase());row.hidden=!visible;if(visible)n++;});document.getElementById('visible-count').textContent=n+' runs shown';}
purpose.addEventListener('change',filterRuns);search.addEventListener('input',filterRuns);
if(chart){const svg=document.getElementById('energy-chart'),ns='http://www.w3.org/2000/svg';const left=60,right=1090,top=20,bottom=255;const points=Object.values(chart.curve).flat();const maxY=Math.max(1,...points.map(p=>p[1]))*1.08;const x=t=>left+t/chart.horizon*(right-left),y=v=>bottom-v/maxY*(bottom-top);
function element(tag,attrs,text){const e=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,String(v)));if(text!==undefined)e.textContent=text;svg.append(e);return e;}
for(let j=0;j<=4;j++){const value=maxY*j/4;const yy=y(value);element('line',{x1:left,y1:yy,x2:right,y2:yy,stroke:'#e2e9f0'});element('text',{x:left-10,y:yy+4,'text-anchor':'end',fill:'#566a80','font-size':11},value.toFixed(1)+' J');}
for(let t=0;t<=chart.horizon;t+=20){element('text',{x:x(t),y:277,'text-anchor':'middle',fill:'#566a80','font-size':11},t+' s');}
Object.entries(chart.curve).forEach(([node,data],i)=>{const color=['#07838b','#725ac1'][i%2];element('polyline',{points:data.map(p=>x(p[0])+','+y(p[1])).join(' '),fill:'none',stroke:color,'stroke-width':2.5});data.forEach(p=>{const dot=element('circle',{cx:x(p[0]),cy:y(p[1]),r:2,fill:color});const title=document.createElementNS(ns,'title');title.textContent='Node '+node+' · '+p[0].toFixed(3)+' s · '+p[1].toFixed(4)+' J';dot.append(title);});});
[['FND',chart.lifetime.fnd.time_ms,'#ab570b'],['Service crossing',chart.lifetime.functional.crossing_ms,'#607689'],['Confirmed',chart.lifetime.functional.confirmation_ms,'#607689']].forEach(([label,time,color],i)=>{if(time==null)return;const xx=x(time/1000);element('line',{x1:xx,y1:top,x2:xx,y2:bottom,stroke:color,'stroke-dasharray':'4 4'});element('text',{x:xx+5,y:top+12+i*15,fill:color,'font-size':10},label);});element('text',{x:(left+right)/2,y:298,'text-anchor':'middle',fill:'#566a80','font-size':11},'Global simulation time');}
</script></body></html>'''
